<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {useCampus} from '../stores/campus'
import AppIcon from './AppIcon.vue'
import CardBalanceChart from './CardBalanceChart.vue'
const props=defineProps<{mode:'card'|'spend',dark:boolean,active:boolean}>(),campus=useCampus()
const now=new Date(),currentMonth=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`
const month=ref(currentMonth),span=ref(6),range=ref('30'),kind=ref('all'),page=ref(1)
const data=ref<any>(null),history=ref<any>({points:[]}),ledger=ref<any>({items:[]}),loading=ref(false),error=ref(''),binding=ref<any>(null),bindingBusy=ref(false),refreshing=ref(false),removeBusy=ref(false)
const owner=campus.studentId
let epoch=0,ledgerEpoch=0,historyEpoch=0,poll:ReturnType<typeof setTimeout>|undefined,pollUntil=0,disposed=false
const bound=computed(()=>data.value?.card?.bound??campus.dashboard?.card?.bound)
const selected=computed(()=>data.value?.selected||{})
const bars=computed(()=>{const rows=data.value?.months||[],max=Math.max(1,...rows.filter((m:any)=>m.complete).map((m:any)=>Math.abs(Number(m.expense))));return rows.map((m:any)=>({...m,height:m.complete?Math.max(3,Math.abs(Number(m.expense))/max*100):0}))})
const merchantMax=computed(()=>Math.max(1,...(data.value?.merchants||[]).map((m:any)=>Number(m.amount))))
const money=(value:unknown)=>campus.masked?'••••':value===null||value===undefined?'—':Number(value).toFixed(2)
const dateText=(s:string)=>s?s.slice(5,16).replace('T',' '):'尚未同步'
const monthText=(s:string)=>s.slice(0,4)+'年'+Number(s.slice(5))+'月'
const kindNames:Record<string,string>={expense:'消费',topup:'充值',refund:'退款',topup_reversal:'充值撤销',other:'其他'}
function notify(s:string){uni.showToast({title:s,icon:'none'})}
function queuePoll(){clearTimeout(poll);if(!disposed&&props.active&&Date.now()<pollUntil&&(binding.value||data.value?.syncing||bound.value&&!selected.value.complete)){poll=setTimeout(()=>void load(false),5000)}}
async function load(show=true){
 const id=++epoch;loading.value=true;if(show)error.value=''
 try{const result=await campus.cardOverview(month.value,span.value);if(disposed||id!==epoch||owner!==campus.studentId)return;data.value=result;if(campus.dashboard){campus.dashboard.card=result.card;campus.dashboard.spending=result.spending}if(result.card.bound&&binding.value&&Date.parse(result.card.authorization_updated_at||'')>=Date.parse(binding.value.expires_at)-600000){binding.value=null;notify('校园卡已绑定')}await Promise.all([loadLedger(),loadHistory()])}
 catch(e){if(!disposed&&id===epoch)error.value=(e as Error).message}
 finally{if(!disposed&&id===epoch){loading.value=false;queuePoll()}}
}
async function loadLedger(more=false){const id=++ledgerEpoch,at=month.value,filter=kind.value,targetPage=more?page.value+1:1;try{const result=await campus.cardTransactions(at,filter,targetPage);if(disposed||id!==ledgerEpoch||owner!==campus.studentId)return;ledger.value={...result,items:more?[...ledger.value.items,...result.items]:result.items};page.value=targetPage}catch(e){if(!disposed&&id===ledgerEpoch)error.value=(e as Error).message}}
async function loadHistory(){const id=++historyEpoch;try{const result=await campus.cardHistory(range.value);if(!disposed&&id===historyEpoch&&owner===campus.studentId)history.value=result}catch(e){if(!disposed&&id===historyEpoch)error.value=(e as Error).message}}
async function bind(){await campus.cardBinding();await load();notify('已恢复虚构校园卡数据')}

async function refresh(){if(refreshing.value)return;refreshing.value=true;pollUntil=Date.now()+180000;try{await load()}finally{refreshing.value=false}}
function changeMonth(e:any){month.value=e.detail.value;pollUntil=Date.now()+180000;void load()}
function selectMonth(s:string){month.value=s;pollUntil=Date.now()+180000;void load()}
function selectKind(s:string){kind.value=s;void loadLedger()}
function selectRange(s:string){range.value=s;void loadHistory()}
function unbind(){uni.showModal({title:'移除演示绑定',content:'只清除当前内存中的演示绑定状态。',success:async r=>{if(!r.confirm||removeBusy.value)return;removeBusy.value=true;try{await campus.cardUnbind();binding.value=null;await load();notify('已移除演示绑定')}catch(e){notify((e as Error).message)}finally{removeBusy.value=false}}})}
watch(()=>props.active,active=>{clearTimeout(poll);if(active){if(!binding.value)pollUntil=Date.now()+180000;void load(false)}})
watch(span,()=>void load())
onMounted(()=>{pollUntil=Date.now()+180000;void load()})
onUnmounted(()=>{disposed=true;epoch++;ledgerEpoch++;historyEpoch++;clearTimeout(poll);binding.value=null})
</script>
<template>
 <view class="campus-card-details" :class="{'card-dark':dark}">
  <view class="card-hero" :class="{coral:mode==='spend'}">
   <view class="hero-top"><view><AppIcon :name="mode==='card'?'card':'chart'" :size="36"/><text>{{mode==='card'?'校园卡余额':'本月消费'}}</text></view><view class="refresh" @click="refresh"><AppIcon name="refresh" :size="30"/></view></view>
   <view class="hero-amount"><text class="yen">¥</text><text>{{money(mode==='card'?(data?.card?.cardinfo?.cardbal??campus.dashboard?.card?.cardinfo?.cardbal):(data?.spending?.month_total??campus.dashboard?.spending?.month_total))}}</text></view>
   <view class="hero-bottom"><text>{{!bound?'恢复演示数据后显示':mode==='card'?'演示时间 '+dateText(data?.card?.observed_at||''):'扣除退款 · 不含充值'}}</text><text class="hero-status">{{data?.syncing?'同步中':data?.card?.status==='stale'?'上次记录':bound?'虚构校园卡':'未绑定'}}</text></view><view class="orb orb-one"/><view class="orb orb-two"/>
  </view>
  <view v-if="error" class="card-alert" @click="refresh">{{error}} · 点击重试</view>
  <view v-if="data?.card?.status==='stale'" class="card-alert">暂未同步完成，保留上次记录与采集时间。可刷新或恢复演示数据。</view>
  <view v-if="!bound" class="card-panel binding-panel"><text class="binding-title">虚构校园卡</text><text class="binding-copy">仅供界面演示，无需账号、绑定码或电脑助手。</text><button class="card-button" @click="bind">恢复演示数据</button></view>
  <template v-if="bound">
   <view v-if="mode==='card'" class="card-panel"><view class="panel-heading"><view><AppIcon name="balance-trend" :size="33"/><text>余额曲线</text></view><text class="muted">元</text></view><view class="segments mint"><view v-for="item in [{id:'7',label:'7天'},{id:'30',label:'30天'},{id:'90',label:'90天'},{id:'all',label:'全部'}]" :key="item.id" :class="{picked:range===item.id}" @click="selectRange(item.id)">{{item.label}}</view></view><CardBalanceChart :points="history.points||[]" :dark="dark" :masked="campus.masked"/></view>
   <view class="card-panel"><view class="panel-heading"><view><AppIcon name="chart" :size="33"/><text>每月消费</text></view><view class="tiny-switch"><text :class="{chosen:span===6}" @click="span=6">半年</text><text :class="{chosen:span===12}" @click="span=12">一年</text></view></view>
    <view class="month-summary"><view><text>{{monthText(month)}}</text><view><text class="summary-yen">¥</text><text>{{money(selected.expense)}}</text></view></view><text class="month-count">{{selected.complete?selected.count+' 笔消费':'尚未完整同步'}}</text></view>
    <view v-if="campus.masked" class="chart-hidden">消费金额已隐藏</view><view v-else class="bar-chart"><view class="bar-guide guide-top"/><view class="bar-guide guide-mid"/><view class="bar-guide guide-bottom"/><view v-for="bar in bars" :key="bar.month" class="bar-column" :class="{selected:month===bar.month}" @click="selectMonth(bar.month)"><view class="bar-well"><view v-if="bar.complete" class="bar-fill" :class="{negative:Number(bar.expense)<0}" :style="{height:bar.height+'%'}"/><view v-else class="bar-unknown">·</view></view><text>{{Number(bar.month.slice(5))}}</text><view class="bar-dot"/></view></view>
    <view class="chart-legend"><view><view class="legend-dot"/><text>月消费 · 元</text></view><text>点击柱形查看当月</text></view><view v-if="selected.complete" class="month-extras"><view><text>消费</text><text>¥ {{money(selected.gross_expense)}}</text></view><view><text>退款</text><text>¥ {{money(selected.refund)}}</text></view><view><text>充值</text><text>¥ {{money(selected.topup)}}</text></view></view><text v-else class="small-note">未同步的月份以圆点显示，完成同步后再计算总额。</text>
   </view>
   <view v-if="data?.merchants?.length" class="card-panel"><view class="panel-heading"><view><AppIcon name="receipt" :size="32"/><text>消费去向</text></view><text class="muted">当月前五</text></view><view v-for="(item,i) in data.merchants" :key="item.name" class="merchant-row"><text class="merchant-rank">{{String(Number(i)+1).padStart(2,'0')}}</text><view class="merchant-body"><view><text>{{item.name}}</text><text>¥ {{money(item.amount)}}</text></view><view class="merchant-track"><view :style="{width:campus.masked?'0%':Math.max(1,Number(item.amount)/merchantMax*100)+'%'}"/></view></view></view></view>
  </template>
  <view v-if="bound||ledger.items?.length" class="card-panel"><view class="panel-heading"><view><AppIcon name="receipt" :size="32"/><text>交易流水</text></view><picker mode="date" fields="month" start="2020-01" :end="currentMonth" :value="month" @change="changeMonth"><view class="month-picker">{{month}} ⌄</view></picker></view><view class="segments"><view v-for="item in [{id:'all',label:'全部'},{id:'expense',label:'消费'},{id:'topup',label:'充值'},{id:'refund',label:'退款'}]" :key="item.id" :class="{picked:kind===item.id}" @click="selectKind(item.id)">{{item.label}}</view></view>
   <view v-for="item in ledger.items" :key="item.id" class="ledger-row"><view class="ledger-symbol" :class="item.kind"><AppIcon :name="item.kind==='topup'?'card-link':'receipt'" :size="30"/></view><view class="ledger-copy"><text>{{item.merchant||item.event||kindNames[item.kind]}}</text><text>{{dateText(item.at)}} · {{kindNames[item.kind]||'其他'}}</text><text v-if="item.summary&&item.summary!==item.event" class="ledger-note">{{item.summary}}</text></view><text class="ledger-amount" :class="{positive:Number(item.amount)>0}">{{campus.masked?'••••':(Number(item.amount)>0?'+':'')+item.amount}}</text></view>
   <view v-if="!ledger.items?.length" class="ledger-empty"><AppIcon name="receipt" :size="55"/><text>{{loading||data?.syncing?'正在加载演示流水':selected.complete?'该月没有此类交易':'该月流水尚未同步'}}</text></view><view v-if="ledger.has_more" class="load-more" @click="loadLedger(true)">查看更多流水 ↓</view><text v-else-if="ledger.items?.length" class="small-note">共 {{ledger.total}} 条记录</text>
  </view>
  <view v-if="bound" class="card-footer"><text @click="bind">恢复演示数据</text><text @click="unbind">{{removeBusy?'正在解除…':'移除演示绑定'}}</text></view><text class="privacy-foot">全部为本地虚构数据 · 无真实授权或采集</text>
 </view>
</template>
<style scoped lang="scss">
