der-radius:17rpx;color:var(--muted)}.tiny-switch>.chosen{background:var(--panel);color:#df917f;font-weight:600}.month-summary{display:flex;align-items:center;justify-content:space-between;margin:31rpx 2rpx 24rpx}.month-summary>view>text{display:block;color:var(--muted);font-size:20rpx}.month-summary>view>view{font-size:45rpx;font-weight:650;margin-top:10rpx;display:flex;align-items:baseline;gap:8rpx;letter-spacing:-1rpx}.summary-yen{font-size:25rpx;font-weight:400}.month-count{font-size:19rpx;color:var(--muted);background:var(--soft);padding:10rpx 16rpx;border-radius:20rpx}.bar-chart{height:245rpx;display:flex;align-items:stretch;gap:14rpx;position:relative;margin:0 5rpx}.bar-guide{position:absolute;left:0;right:0;border-top:1rpx dashed var(--line);pointer-events:none}.guide-top{top:7rpx}.guide-mid{top:96rpx}.guide-bottom{top:185rpx}.bar-column{position:relative;flex:1;display:flex;align-items:center;flex-direction:column;min-width:0}.bar-well{height:185rpx;width:64%;display:flex;align-items:flex-end;justify-content:center;z-index:1}.bar-fill{width:100%;max-width:48rpx;min-height:4rpx;border-radius:9rpx 9rpx 3rpx 3rpx;background:linear-gradient(0deg,#edb1a0,#f5d4c4);transition:height .35s}.bar-fill.negative{background:linear-gradient(0deg,#a5d9c7,#d4eee3)}.selected .bar-fill{background:linear-gradient(0deg,#df947f,#f5bc9c);box-shadow:0 5rpx 12rpx #df947f20}.selected .bar-fill.negative{background:#32b995}.bar-column>text{font-size:19rpx;color:var(--muted);margin-top:12rpx}.bar-column.selected>text{color:#de927c;font-weight:650}.bar-dot{width:5rpx;height:5rpx;border-radius:50%;margin-top:7rpx}.selected .bar-dot{background:#de927c}.bar-unknown{color:var(--muted);font-size:30rpx;line-height:30rpx}.chart-legend,.chart-legend>view{display:flex;align-items:center;justify-content:space-between;gap:9rpx;color:var(--muted);font-size:18rpx}.legend-dot{width:12rpx;height:12rpx;background:#edb3a0;border-radius:4rpx}.month-extras{display:flex;border-top:1rpx solid var(--line);margin-top:23rpx;padding-top:22rpx;gap:12rpx}.month-extras>view{flex:1}.month-extras text{display:block;font-size:19rpx;color:var(--muted)}.month-extras text+text{font-size:25rpx;font-weight:600;color:var(--ink);margin-top:9rpx}.merchant-row{display:flex;align-items:center;gap:17rpx;margin-top:25rpx}.merchant-rank{font-size:22rpx;color:var(--muted);font-style:italic}.merchant-body{flex:1;min-width:0}.merchant-body>view:first-child{display:flex;justify-content:space-between;font-size:22rpx;gap:12rpx}.merchant-body>view:first-child>text:first-child{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.merchant-body>view:first-child>text+text{flex-shrink:0;font-variant-numeric:tabular-nums}.merchant-track{height:7rpx;border-radius:8rpx;background:var(--soft);margin-top:12rpx}.merchant-track>view{height:100%;border-radius:8rpx;background:linear-gradient(90deg,#dbad98,#f1d8c5)}.month-picker{font-size:22rpx;font-weight:400;color:var(--muted);padding:8rpx 12rpx;background:var(--soft);border-radius:14rpx}.ledger-row{display:flex;align-items:center;gap:17rpx;padding:24rpx 0;border-bottom:1rpx solid var(--line)}.ledger-row:last-of-type{border-bottom:0}.ledger-symbol{width:65rpx;height:65rpx;flex-shrink:0;border-radius:21rpx;background:var(--soft);display:flex;align-items:center;justify-content:center}.ledger-symbol.topup{background:#32b99514}.ledger-copy{flex:1;min-width:0}.ledger-copy>text{display:block;font-size:24rpx;line-height:1.5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ledger-copy>text+text{font-size:19rpx;color:var(--muted);margin-top:5rpx}.ledger-note{font-size:18rpx!important}.ledger-amount{font-size:27rpx;font-weight:600;font-variant-numeric:tabular-nums;white-space:nowrap}.positive{color:#26b18a}.ledger-empty{min-height:210rpx;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:17rpx;font-size:22rpx;color:var(--muted)}.load-more{padding:25rpx 0 7rpx;text-align:center;color:#28a785;font-size:23rpx}.binding-panel{text-align:center;padding:35rpx 30rpx}.binding-icon{width:105rpx;height:105rpx;display:flex;align-items:center;justify-content:center;background:linear-gradient(145deg,#35ba9718,#53a9d610);border-radius:32rpx;margin:0 auto 22rpx}.binding-title{font-size:31rpx;font-weight:650;display:block}.binding-copy{display:block;color:var(--muted);font-size:23rpx;line-height:1.8;margin:13rpx 16rpx}.binding-steps{text-align:left;margin:29rpx 0}.binding-steps>view{display:flex;align-items:center;gap:16rpx;margin:20rpx 0;font-size:22rpx;line-height:1.7;color:var(--muted)}.step-no{background:#29b28e15;color:#23a67f;border-radius:50%;width:38rpx;height:38rpx;line-height:38rpx;text-align:center;font-size:21rpx;flex-shrink:0;font-weight:600}.card-button{border:0;background:linear-gradient(110deg,#2db88f,#359c94);color:white;border-radius:21rpx;font-size:26rpx;line-height:86rpx}.card-button:after,.outline-button:after{border:0}.small-note{display:block;color:var(--muted);font-size:19rpx;line-height:1.8;margin-top:18rpx;text-align:center}.command-box{background:var(--soft);padding:19rpx;text-align:left;border-radius:18rpx;max-height:180rpx;overflow:auto;margin:20rpx 0;color:var(--muted);font-family:monospace;font-size:18rpx;word-break:break-all;line-height:1.7}.binding-meta{display:flex;align-items:center;justify-content:space-between;font-size:18rpx;color:var(--muted);margin-top:17rpx}.binding-meta>text+text{color:#29ac86}.outline-button{font-size:23rpx;border-radius:18rpx;background:var(--soft);color:var(--ink);line-height:75rpx;margin-top:18rpx}.card-alert{background:#ebaf4e14;color:#c08e3c;border-radius:17rpx;padding:19rpx 23rpx;margin-top:20rpx;font-size:21rpx;line-height:1.6}.card-footer{display:flex;align-items:center;justify-content:center;gap:40rpx;margin:30rpx 0;font-size:22rpx;color:var(--muted)}.privacy-foot{display:block;text-align:center;font-size:18rpx;color:var(--muted);line-height:1.8;margin:24rpx 0}.chart-hidden{height:245rpx;display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:23rpx}
.card-dark .card-hero{background:linear-gradient(130deg,#244e47,#255b51);color:#c6efdf}.card-dark .card-hero.coral{background:linear-gradient(130deg,#553f3c,#6a4940);color:#f4d2c3}.card-dark .hero-status,.card-dark .hero-top .refresh{background:#ffffff13}.card-dark .orb{border-color:#ffffff08}
</style>
